import { readFile, writeFile } from 'node:fs/promises';
import { mdiLightbulbOutline, mdiThermostat, mdiSpeaker, mdiCreationOutline, mdiMinus, mdiPlus, mdiPlay, mdiPause, mdiSkipPrevious, mdiSkipNext, mdiPlayOutline, mdiCircleOutline, mdiPowerPlugOutline, mdiWeatherPartlyCloudy, mdiWeatherWindy, mdiWaterPercent, mdiSolarPowerVariantOutline, mdiHomeOutline, mdiTransmissionTower, mdiBatteryOutline, mdiChartBar, mdiClose, mdiChevronRight, mdiArrowTopRight } from '@mdi/js';

const icons = { 'mdi:lightbulb-outline': mdiLightbulbOutline, 'mdi:thermostat': mdiThermostat, 'mdi:speaker': mdiSpeaker, 'mdi:creation-outline': mdiCreationOutline, 'mdi:minus': mdiMinus, 'mdi:plus': mdiPlus, 'mdi:play': mdiPlay, 'mdi:pause': mdiPause, 'mdi:skip-previous': mdiSkipPrevious, 'mdi:skip-next': mdiSkipNext, 'mdi:play-outline': mdiPlayOutline, 'mdi:circle-outline': mdiCircleOutline, 'mdi:power-plug-outline': mdiPowerPlugOutline, 'mdi:weather-partly-cloudy': mdiWeatherPartlyCloudy, 'mdi:weather-windy': mdiWeatherWindy, 'mdi:water-percent': mdiWaterPercent, 'mdi:solar-power-variant-outline': mdiSolarPowerVariantOutline, 'mdi:home-outline': mdiHomeOutline, 'mdi:transmission-tower': mdiTransmissionTower, 'mdi:battery-outline': mdiBatteryOutline, 'mdi:chart-bar': mdiChartBar, 'mdi:close': mdiClose, 'mdi:chevron-right': mdiChevronRight, 'mdi:arrow-top-right': mdiArrowTopRight };
const bundle = (await readFile('dist/still-cards.js', 'utf8')).replace(/\/\/# sourceMappingURL=.*$/m, '');
const html = `<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Still cards preview</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;--still-accent:#0066d6;--still-surface:#fff;--still-text:#1c1c1e;--still-muted:#63636c;--still-subtle:#f2f2f7;--still-border-color:#e5e5ea;--still-radius:24px;--still-on-accent:#fff;--preview-muted:#63636c;--preview-border:#e5e5ea;--preview-control:#f2f2f7;--preview-text:#1c1c1e;--preview-canvas:#f2f2f7}
:root[data-mode=dark]{--still-light-color:#ffd074;--still-solar-color:#72d6a1;--still-toggle-color:#30b759;color-scheme:dark;--still-accent:#80b5ff;--still-surface:#1c1c1e;--still-text:#f5f5f7;--still-muted:#aaaab2;--still-subtle:#2c2c2e;--still-border-color:#38383d;--still-on-accent:#101827;--preview-muted:#aaaab2;--preview-border:#38383d;--preview-control:#2c2c2e;--preview-text:#f5f5f7;--preview-canvas:#0b0b10}
*{box-sizing:border-box}body{margin:0;background:transparent;color:var(--preview-text)}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible{outline:2px solid var(--still-accent);outline-offset:3px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:16px;padding:16px;background:var(--still-surface);border:1px solid var(--preview-border);border-radius:var(--radius,14px)}.mode{display:flex;gap:4px;background:var(--preview-control);padding:3px;border-radius:9px}.mode button{border:0;background:transparent;padding:9px 12px;border-radius:7px;font-size:12px;min-height:36px}.mode button[aria-pressed=true]{background:var(--still-accent);color:var(--still-on-accent)}.palette{display:flex;gap:9px;margin-left:auto}.palette button{width:28px;height:28px;border:0;border-radius:50%;background:var(--swatch);position:relative}.palette button[aria-pressed=true]:after{content:'';position:absolute;inset:-3px;border:1px solid var(--swatch);border-radius:50%}.finish{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--preview-muted)}select{background:var(--preview-control);border:1px solid var(--preview-border);border-radius:7px;padding:8px;font-size:12px;min-height:36px}.cards{padding:16px;border-radius:24px;background:var(--preview-canvas);display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start}still-card{height:auto}.note{font-size:11px;line-height:1.6;color:var(--muted-foreground,#63636c);margin:14px 0 0}.note span{color:inherit}@media(max-width:480px){.cards{grid-template-columns:minmax(0,1fr)}.toolbar{gap:14px}.finish{width:100%}.palette{margin-left:auto}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important}}
</style></head><body>
<div class="toolbar"><div class="mode" role="group" aria-label="Appearance"><button data-mode="light" aria-pressed="true">Daylight</button><button data-mode="dark" aria-pressed="false">After dark</button></div><div class="palette" role="group" aria-label="Accent"><button data-accent="0" aria-label="Blue accent" aria-pressed="true" style="--swatch:#0066d6"></button><button data-accent="1" aria-label="Clay accent" aria-pressed="false" style="--swatch:#996956"></button><button data-accent="2" aria-label="Ocean accent" aria-pressed="false" style="--swatch:#4a6f91"></button></div><label class="finish">Finish <select id="finish"><option value="soft">Soft</option><option value="outlined">Outline</option><option value="minimal">Minimal</option></select></label></div>
<div class="cards" id="cards"></div><p class="note" id="feedback" role="status">Interactive preview <span>·</span> Sample devices. Tap a card for details, try a preset, or change the style.</p>
<script type="module">${bundle}</script>
<script type="module">
await customElements.whenDefined('still-card');
const paths=${JSON.stringify(icons)};
class PreviewIcon extends HTMLElement{set icon(value){this._icon=value;this.draw()}get icon(){return this._icon}connectedCallback(){this.draw()}draw(){this.innerHTML='<svg viewBox="0 0 24 24" width="100%" height="100%" fill="currentColor" aria-hidden="true"><path d="'+(paths[this._icon]||paths['mdi:circle-outline'])+'"></path></svg>'}}
if(!customElements.get('ha-icon'))customElements.define('ha-icon',PreviewIcon);
const state=(entity_id,state,friendly_name,attributes={})=>({entity_id,state,attributes:{friendly_name,...attributes}});
const list=[state('light.reading','on','Reading light',{brightness:166,supported_color_modes:['brightness']}),state('climate.living','heat','Living room climate',{temperature:22,current_temperature:21.5,min_temp:7,max_temp:35,target_temp_step:.5,supported_features:17,preset_mode:'home',preset_modes:['home','eco','away'],hvac_modes:['off','heat','cool']}),state('media_player.living','playing','A little background music',{media_title:'Evening, slowly',media_artist:'Still Sessions · Ambient',volume_level:.35,supported_features:16437}),state('switch.coffee','off','Coffee machine'),state('weather.home','partlycloudy','Outside',{temperature:18,temperature_unit:'°C',humidity:62,wind_speed:8,wind_speed_unit:'km/h',apparent_temperature:17}),state('sensor.solar','4.2','Solar & energy',{unit_of_measurement:'kW'}),state('sensor.home','1600','Home',{unit_of_measurement:'W'}),state('sensor.grid','-1400','Grid',{unit_of_measurement:'W'}),state('sensor.battery','78','Battery',{unit_of_measurement:'%'}),state('sensor.today','18.6','Solar today',{unit_of_measurement:'kWh'})];
const configs=[{type:'custom:still-light-card',entity:'light.reading'},{type:'custom:still-climate-card',entity:'climate.living'},{type:'custom:still-media-card',entity:'media_player.living'},{type:'custom:still-toggle-card',entity:'switch.coffee'},{type:'custom:still-weather-card',entity:'weather.home'},{type:'custom:still-solar-card',entity:'sensor.solar',subtitle:'Live energy flow',solar:{home_power:'sensor.home',grid_power:'sensor.grid',battery_level:'sensor.battery',energy_today:'sensor.today'}}];
const cards=[];let mode='light',accent=0;
let hass={states:Object.fromEntries(list.map(e=>[e.entity_id,e])),config:{unit_system:{temperature:'°C'}},callService:async(domain,service,data)=>{const old=hass.states[data.entity_id];const entity={...old,attributes:{...old.attributes}};if(service==='toggle')entity.state=entity.state==='on'?'off':'on';if(service==='turn_on')entity.state='on';if(service==='turn_off')entity.state='off';if(data.brightness_pct!==undefined)entity.attributes.brightness=data.brightness_pct/100*255;if(service==='set_preset_mode')entity.attributes.preset_mode=data.preset_mode;if(service==='set_temperature')entity.attributes.temperature=data.temperature;if(service==='set_hvac_mode')entity.state=data.hvac_mode;if(service==='media_pause')entity.state='paused';if(service==='media_play')entity.state='playing';if(service==='volume_set')entity.attributes.volume_level=data.volume_level;if(service==='media_next_track')entity.attributes.media_title='Sunday, slowly';if(service==='media_previous_track')entity.attributes.media_title='Evening, slowly';hass={...hass,states:{...hass.states,[entity.entity_id]:entity}};if(domain==='scene'){hass.states['light.reading']={...hass.states['light.reading'],state:'on',attributes:{...hass.states['light.reading'].attributes,brightness:60}};hass.states['media_player.living']={...hass.states['media_player.living'],state:'paused'}}cards.forEach(card=>card.hass=hass);document.querySelector('#feedback').textContent=domain==='scene'?'A slower evening. Lights dimmed, music paused.':'Updated · '+old.attributes.friendly_name;}};
configs.forEach(config=>{const card=document.createElement('still-card');card.setConfig(config);card.hass=hass;cards.push(card);document.querySelector('#cards').append(card)});
document.addEventListener('hass-more-info',event=>{const entity=hass.states[event.detail.entityId];document.querySelector('#feedback').textContent=entity.attributes.friendly_name+' · '+entity.state+' (sample device)'});
const colors=[['#0066d6','#80b5ff'],['#996956','#d9ad95'],['#4a6f91','#a0bbd9']];
const applyAccent=()=>document.documentElement.style.setProperty('--still-accent',colors[accent][mode==='dark'?1:0]);
document.querySelectorAll('.mode button').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;document.documentElement.dataset.mode=mode;document.querySelectorAll('.mode button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));applyAccent()}));
document.querySelectorAll('[data-accent]').forEach(button=>button.addEventListener('click',()=>{accent=Number(button.dataset.accent);document.querySelectorAll('[data-accent]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));applyAccent()}));
document.querySelector('#finish').addEventListener('change',event=>{cards.forEach((card,index)=>card.setConfig({...configs[index],variant:event.target.value}))});
await Promise.all(cards.map(card=>card.updateComplete));
console.log('Still preview ready: six production cards.');
</script></body></html>`;
await writeFile('docs/preview.html', html);
console.log('Self-contained interactive preview saved to docs/preview.html.');
